import{_ as t,o,i as a,a9 as s}from"./chunks/framework.DuwpaNh0.js";const h=JSON.parse('{"title":"Modules Manifest","description":"","frontmatter":{"title":"Modules Manifest"},"headers":[],"relativePath":"modules/5-advanced/manifest.md","filePath":"modules/5-advanced/manifest.md","lastUpdated":1787965859000}'),n={name:"modules/5-advanced/manifest.md"};function i(d,e,l,r,c,u){return o(),a("div",null,e[0]||(e[0]=[s('<h1 id="the-modules-manifest" tabindex="-1">The Modules Manifest <a class="header-anchor" href="#the-modules-manifest" aria-label="Permalink to &quot;The Modules Manifest&quot;">​</a></h1><p>Every bundle has its own <a href="./../2-bundle/1-overview/1-overview.html#manifestjson">manifest</a>, but there is also a combined manifest, which actually consists of all the separate bundles&#39; manifests combined into one. This serves as a easy file for <code>js-slang</code> to check against when loading bundles and also to make sure that the bundle being loaded actually exists.</p><p>The modules manifest is located at <code>build/modules.json</code>. It is not intended to be modified directly. Rather, you should modify the fields in your bundle&#39;s <code>package.json</code> and <code>manifest.json</code>.</p><p>The manifest is generated automatically during build time, but if you want to regenerate the manifest, you can use <code>yarn buildtools manifest</code> from the root of the repository to regenerate the manifest.</p><h2 id="documentation-site-visibility" tabindex="-1">Documentation site visibility <a class="header-anchor" href="#documentation-site-visibility" aria-label="Permalink to &quot;Documentation site visibility&quot;">​</a></h2><p>Separately, <a href="https://github.com/source-academy/modules/blob/master/conductor-modules.json" target="_blank" rel="noreferrer"><code>conductor-modules.json</code></a> at the root of the repository is a manually maintained allowlist of bundles shown on the <a href="https://source-academy.github.io/modules/documentation/" target="_blank" rel="noreferrer">documentation site</a>. Bundles that haven&#39;t been migrated to Conductor yet don&#39;t work correctly in the current Source Academy frontend, so they&#39;re deliberately left off this list to avoid confusing students with documentation for modules they can&#39;t actually use.</p><p>Once your bundle has been migrated to Conductor and is ready for students to see, add its directory name to <code>conductor-modules.json</code> in the same pull request. This file only controls the documentation site - it has no effect on <code>build/modules.json</code> above, so it doesn&#39;t change which modules are actually loadable in the Source Academy IDE.</p>',7)]))}const f=t(n,[["render",i]]);export{h as __pageData,f as default};
